// Environmental Monitoring AI Agent Reasoning
const aqiData = $input.first().json || {};
const aqi = aqiData.aqi || 382;
const stationName = aqiData.station_name || 'Anand Vihar Eco Monitoring Station';
const pm25 = aqiData.pollutants?.pm25?.value || 245.8;
const pm10 = aqiData.pollutants?.pm10?.value || 395.2;
const windSpeed = aqiData.meteorological?.wind_speed_kmh || 3.2;
const thermalInversion = aqiData.meteorological?.thermal_inversion_detected || true;

// Determine Category and Alerts
let category = 'VERY_POOR';
const alerts = [];
const recommendations = [];
let escalate = false;

if (aqi >= 401) {
  category = 'SEVERE';
  alerts.push(`EMERGENCY: AQI has breached SEVERE threshold (${aqi}) at ${stationName}.`);
  recommendations.push('Trigger GRAP Stage IV emergency: Total ban on non-essential construction and demolition.');
  recommendations.push('Deploy heavy anti-smog guns and motorized water tankers along arterial roads.');
  recommendations.push('Issue public health emergency broadcast: N95 masks mandatory for sensitive groups, restrict outdoor school activities.');
  escalate = true;
} else if (aqi >= 301) {
  category = 'VERY_POOR';
  alerts.push(`CRITICAL: AQI is in VERY POOR category (${aqi}) at ${stationName}.`);
  recommendations.push('Deploy mobile Anti-Smog Gun units at major traffic intersections and dust corridors.');
  recommendations.push('Intensify mechanical street sweeping and water sprinkling along Anand Vihar corridor.');
  recommendations.push('Enforce strict ban on open garbage burning and DG set usage in surrounding industrial zones.');
  escalate = true;
} else if (aqi >= 201) {
  category = 'POOR';
  alerts.push(`ADVISORY: AQI elevated to POOR (${aqi}).`);
  recommendations.push('Increase frequency of dust suppression water misting.');
} else {
  category = 'SATISFACTORY';
  alerts.push(`AQI within acceptable limits (${aqi}).`);
  recommendations.push('Maintain standard environmental monitoring.');
}

if (thermalInversion && windSpeed < 5) {
  alerts.push('Meteorological Warning: Low wind speed (< 5 km/h) and thermal inversion layer trapping particulate matter near surface.');
}

const output = {
  reading_id: 'ENV-RDG-' + Date.now(),
  station_id: aqiData.station_id || 'STN-ANAND-VIHAR-03',
  source_agent: 'environmental_monitoring_agent',
  aqi_report: `Station: ${stationName} | Current AQI: ${aqi} (${category}) | Dominant Pollutant: PM2.5 (${pm25} ug/m3, 4x WHO standard) | PM10: ${pm10} ug/m3 | Meteorological condition: Stagnant dispersion (Wind: ${windSpeed} km/h).`,
  aqi_value: aqi,
  dominant_pollutant: 'PM2.5',
  category: category,
  affected_locations: [stationName, 'East Municipal Zone', 'Interstate Bus Terminal Corridor'],
  environmental_alerts: alerts,
  recommendations: recommendations,
  escalate_to_command: escalate,
  command_alert_headline: `[ENVIRONMENTAL ALERT - ${category}] AQI Breached ${aqi} at ${stationName}`
};

return output;
